(** Generates the verilog that the Tiny Tapeout flow consumes.

    [dune exec hardcaml/bin/generate.exe -- -output-file src/tt_um_uart_tx.v] *)

open! Core
open Hardcaml
open Tt_protocol_emulator

let generate ~output_file ~(config : Uart_tx.Config.t) =
  let scope = Scope.create ~flatten_design:false () in
  let circuit = Tt_top.circuit ~config scope in
  let rtl =
    Rtl.create Verilog [ circuit ] ~database:(Scope.circuit_database scope)
    |> Rtl.full_hierarchy
    |> Rope.to_string
  in
  let header =
    [%string
      "/* Generated by hardcaml - do not edit.\n\
      \   Regenerate with `make rtl`.\n\
      \   clock = %{config.clock_frequency_hz#Int}Hz, baud = \
       %{config.baud_rate#Int}, cycles/bit = \
       %{Uart_tx.Config.cycles_per_bit config#Int} */\n\
       `default_nettype none\n"]
  in
  let contents = header ^ rtl ^ "\n`default_nettype wire\n" in
  Out_channel.write_all output_file ~data:contents;
  printf "wrote %s (%d bytes)\n" output_file (String.length contents)
;;

let command =
  Command.basic
    ~summary:"generate the Tiny Tapeout verilog from the hardcaml design"
    [%map_open.Command
      let output_file =
        flag
          "output-file"
          (optional_with_default "../src/tt_um_uart_tx.v" string)
          ~doc:"FILE verilog output path"
      and clock_frequency_hz =
        flag
          "clock-frequency-hz"
          (optional_with_default Uart_tx.Config.default.clock_frequency_hz int)
          ~doc:"HZ clock frequency the design is run at"
      and baud_rate =
        flag
          "baud-rate"
          (optional_with_default Uart_tx.Config.default.baud_rate int)
          ~doc:"BAUD uart baud rate"
      in
      fun () -> generate ~output_file ~config:{ clock_frequency_hz; baud_rate }]
;;

let () = Command_unix.run command
